        public Contains(List<TaggedUnbox> members) {
            int sum = 0;
            for (TaggedUnbox u : members) {
                itemToOffset.put(u.tag(), sum);
                sum += u.bitWidth();
            }
            bitWidth = sum;
        }

        @Override
